function makeDefault(){return {version:1,shopDate:'2000-04-17',items:structuredClone([...sample,...EXTRA_CATALOG]),catalogEdition:2,mechanicsEdition:1,profiles:[{id:'visitor',name:'Visitante',wallet:25000}],currentProfile:'visitor',carts:{visitor:{}},sales:[],saleNo:0,terminal:{visitor:{solved:[],unlocks:[],access:false}}};}
function validCategory(c){return Object.prototype.hasOwnProperty.call(CATEGORY,c)&&c!=='all'}
function safeImage(v){if(typeof v!=='string')return '';return /^(data:image\/(png|jpeg|webp|gif);base64,|https?:\/\/)/i.test(v)?v:''}
function cleanItem(o){return {id:String(o.id||uid()).slice(0,72),category:validCategory(o.category)?o.category:'especial',name:String(o.name||'Item sem nome').slice(0,120),subtitle:String(o.subtitle||'').slice(0,100),description:String(o.description||'').slice(0,1200),effect:String(o.effect||'').slice(0,1200),price:Math.max(0,Math.floor(Number(o.price)||0)),rarity:['common','rare','limited'].includes(o.rarity)?o.rarity:'common',stock:Math.max(-1,Math.floor(Number(o.stock??0)||0)),icon:ICONS.includes(o.icon)?o.icon:'especial',image:safeImage(o.image),visible:o.visible!==false,group:Object.hasOwn(ITEM_GROUPS,o.group)&&o.group!=='all'?o.group:'base',sourcePR:o.sourcePR===null||o.sourcePR===undefined?null:(Number.isFinite(Number(o.sourcePR))?Number(o.sourcePR):null)};}
function cleanState(o){if(!o||!Array.isArray(o.items)||!Array.isArray(o.profiles))throw Error('Formato de save inválido.');const ids=new Set();const items=o.items.slice(0,2000).map(cleanItem).map(it=>{if(DEFAULT_ITEM_IMAGES[it.id]&&!it.image)it.image=DEFAULT_ITEM_IMAGES[it.id];if(EXTRA_ITEM_IMAGES[it.id]&&!it.image)it.image=EXTRA_ITEM_IMAGES[it.id];while(ids.has(it.id))it.id=uid();ids.add(it.id);return it});if((Number(o.catalogEdition)||0)<2){for(const fresh of EXTRA_CATALOG){if(!ids.has(fresh.id)){items.push({...fresh});ids.add(fresh.id)}}}if((Number(o.mechanicsEdition)||0)<TANAKA_MECHANICS_EDITION){
 for(const item of items){
   const updated=TANAKA_ITEM_EFFECTS[item.id];
   if(!updated)continue;
   if(item.effect===TANAKA_LEGACY_EFFECTS[item.id]||!item.effect)item.effect=updated;
   if(item.id==='sh-009'&&item.category==='arma')item.category='acessorio';
   if((item.id==='sh-013'||item.id==='sh-014')&&item.category==='protecao')item.category='acessorio';
   if(item.id==='sh-009'&&item.name==='Faca de Colecionador')item.name='Lâmina de Colecionador';
 }
}
const pids=new Set();const profiles=o.profiles.slice(0,150).filter(p=>p&&p.id).map(p=>({id:String(p.id).slice(0,72),name:String(p.name||'Cliente').slice(0,80),wallet:Math.max(0,Math.floor(Number(p.wallet)||0))})).filter(p=>{if(pids.has(p.id))return false;pids.add(p.id);return true});if(!profiles.length)profiles.push({id:'visitor',name:'Visitante',wallet:25000});let carts={};for(const p of profiles){carts[p.id]={};for(const [id,q] of Object.entries(o.carts?.[p.id]||{})){if(items.some(it=>it.id===id)){const n=Math.floor(Number(q)||0);if(n>0)carts[p.id][id]=Math.min(n,9999);}}}const terminal={};for(const p of profiles){const raw=o.terminal?.[p.id]||{};terminal[p.id]={solved:Array.isArray(raw.solved)?raw.solved.filter(x=>['easy','medium','hard','nightmare'].includes(x)).slice(0,4):[],unlocks:Array.isArray(raw.unlocks)?raw.unlocks.filter(x=>['night-cache','bside-armory','black-file'].includes(x)).slice(0,3):[],access:raw.access===true};}return {version:1,shopDate:/^\d{4}-\d\d-\d\d$/.test(o.shopDate)?o.shopDate:'2000-04-17',items,catalogEdition:2,mechanicsEdition:1,profiles,currentProfile:profiles.some(p=>p.id===o.currentProfile)?o.currentProfile:profiles[0].id,carts,sales:Array.isArray(o.sales)?o.sales.slice(-300).filter(s=>s&&Array.isArray(s.lines)):[],saleNo:Math.max(0,Math.floor(Number(o.saleNo)||0)),terminal};}
function load(){try{const raw=localStorage.getItem(KEY);return raw?cleanState(JSON.parse(raw)):makeDefault()}catch(e){return makeDefault()}}
let state=load(),filter='all',search='',sort='default',groupFilter='all',adminTab='catalog',editingId=null,editorImage='',toastTimer=null,lastReceipt=null;
let receiptDateDraft=state.shopDate;
function validReceiptDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const [y,m,d]=v.split('-').map(Number);const dt=new Date(Date.UTC(y,m-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d}
function showReceiptDate(v){return validReceiptDate(v)?v.split('-').reverse().join('/'):'ESCOLHA UMA DATA'}
const $=s=>document.querySelector(s),money=n=>'¥'+Math.max(0,Math.round(n)).toLocaleString('ja-JP'),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>`sh-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
const PRECISE_SVG_ICONS=new Set(['consumivel','arma','protecao','acessorio','especial','bottle','coffee','soda','onigiri','bandage','medkit','tape','bat','knife','guitar','mic','jacket','gloves','boots','headphones','charm']);
const icon=(s,cl='')=>{
  if(PRECISE_SVG_ICONS.has(s)) return `<svg class="item-svg ${cl}" aria-hidden="true" viewBox="0 0 64 64"><use href="#i-${s}"></use></svg>`;
  if(ICONS.includes(s)) return `<span class="item-icon item-icon--${s} ${cl}" aria-hidden="true"></span>`;
  return `<svg class="glyph ${cl}" aria-hidden="true"><use href="#i-${['all','cart','edit','disk','clock','plus','search','print','lock','bag'].includes(s)?s:'especial'}"></use></svg>`;
};

function itemGraphic(i){return `<div class="product-graphic ${i.image?'has-photo':''}" data-fallback-icon="${ICONS.includes(i.icon)?i.icon:'especial'}" role="img" aria-label="${esc(ICON_META[i.icon]?.label||'Item')}">${i.image?`<img src="${esc(i.image)}" alt="${esc(i.name)}" loading="lazy" decoding="async" width="192" height="192">`:icon(i.icon)}</div>`}
function mountIconPicker(m,i){
 const form=m.querySelector('#itemForm'),select=form.elements.icon,grid=m.querySelector('.icon-grid'),preview=m.querySelector('.icon-preview'),group=m.querySelector('[data-icon-group]'),search=m.querySelector('[data-icon-search]'),count=m.querySelector('.icon-count');
 const norm=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const previewUpdate=()=>{
   const meta=ICON_META[select.value],hasPhoto=!form.elements.removeImage.checked&&(safeImage(form.elements.imageUrl.value.trim())||editorImage);
   preview.innerHTML=`<div class="icon-preview-art">${hasPhoto?`<img src="${esc(hasPhoto)}" alt="Prévia da foto">`:icon(select.value)}</div><div><b>${esc(meta.label)}</b><small>${hasPhoto?'Foto personalizada ativa. Este ícone fica como reserva.':esc(meta.group)+' // ILUSTRAÇÃO DO ITEM'}</small></div>`;
   preview.querySelector('img')?.addEventListener('error',e=>{e.target.parentElement.innerHTML=icon(select.value);preview.querySelector('small').textContent='Foto indisponível — mostrando o ícone de reserva.'},{once:true});
 };
 const renderPicker=()=>{
   const q=norm(search.value),list=ICON_LIBRARY.filter(v=>(!group.value||v.group===group.value)&&norm(v.label+' '+v.group+' '+v.id).includes(q));
   grid.innerHTML=list.length?list.map(v=>`<button type="button" class="icon-choice" data-icon-choice="${v.id}" aria-pressed="${select.value===v.id}" aria-label="${esc(v.label)}">${icon(v.id)}<span>${esc(v.label)}</span></button>`).join(''):'<div class="icon-grid-empty">Nenhum ícone encontrado. Tente outro nome ou grupo.</div>';
   count.textContent=`${list.length} de ${ICON_LIBRARY.length} ilustrações disponíveis`;
 };
 select.addEventListener('change',()=>{renderPicker();previewUpdate()});
 grid.addEventListener('click',e=>{const b=e.target.closest('[data-icon-choice]');if(!b)return;select.value=b.dataset.iconChoice;grid.querySelectorAll('[data-icon-choice]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));previewUpdate()});
 group.addEventListener('change',renderPicker);search.addEventListener('input',renderPicker);
 form.elements.imageUrl.addEventListener('input',previewUpdate);form.elements.removeImage.addEventListener('change',previewUpdate);
 m.addEventListener('item-photo-ready',previewUpdate);renderPicker();previewUpdate();
}
document.addEventListener('error',e=>{if(!(e.target instanceof HTMLImageElement))return;const p=e.target.closest('[data-fallback-icon]');if(!p)return;p.classList.remove('has-photo');p.innerHTML=icon(p.dataset.fallbackIcon)},true);

function compactStateForStorage(){
 const copy={...state,items:state.items.map(it=>{
   const source=DEFAULT_ITEM_IMAGES[it.id]||EXTRA_ITEM_IMAGES[it.id];
   // Keep custom art. For default artwork, store only the ID and restore on load.
   return source&&it.image===source?{...it,image:''}:it;
 })};
 return JSON.stringify(copy);
}
function save(){try{localStorage.setItem(KEY,compactStateForStorage());return true}catch(e){toast('Armazenamento cheio. Exporte um save e reduza o tamanho das fotos.',true);return false}}
function toast(s,err=false){const t=$('#toast');t.textContent=s;t.classList.toggle('err',err);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500)}
function current(){return state.profiles.find(p=>p.id===state.currentProfile)||state.profiles[0]}
function cart(){return state.carts[state.currentProfile]||(state.carts[state.currentProfile]={})}
function cartLines(){return Object.entries(cart()).map(([id,qty])=>({item:state.items.find(i=>i.id===id),qty:Number(qty)})).filter(l=>l.item&&l.qty>0)}
function cartTotal(){return cartLines().reduce((n,l)=>n+l.item.price*l.qty,0)}
function cartCount(){return cartLines().reduce((n,l)=>n+l.qty,0)}
function currentDate(){const [y,m,d]=state.shopDate.split('-');return `${d}.${m}.${y}`}
function renderHeader(){$('#headerDate').textContent=currentDate();$('#campaignDateChip').textContent=state.shopDate.replaceAll('-','.');$('#headerCartCount').textContent=cartCount();$('#mobileCount').textContent=cartCount();$('#mobileTotal').textContent=money(cartTotal())}
function renderCategories(){const html=Object.entries(CATEGORY).map(([c,[label,glyph]])=>{const n=state.items.filter(i=>i.visible&&(c==='all'||i.category===c)).length;return `<button type="button" class="cat-btn ${filter===c?'active':''}" data-cat="${c}" aria-pressed="${filter===c}">${icon(glyph)}<span>${label}</span><span class="cat-count">${n.toString().padStart(2,'0')}</span></button>`}).join('');$('#categoryNav').innerHTML=html}
function renderCatalog(){let items=state.items.filter(i=>i.visible&&(filter==='all'||i.category===filter)&&(groupFilter==='all'||i.group===groupFilter)&&[i.name,i.subtitle,i.description,i.effect,ITEM_GROUPS[i.group]||''].join(' ').toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')));if(sort==='priceAsc')items.sort((a,b)=>a.price-b.price);if(sort==='priceDesc')items.sort((a,b)=>b.price-a.price);if(sort==='alpha')items.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));if(sort==='stock')items.sort((a,b)=>(b.stock===-1?999999:b.stock)-(a.stock===-1?999999:a.stock));$('#catalogHeading').textContent=(CATEGORY[filter]?.[0]||'CATÁLOGO')+(groupFilter!=='all'?' / '+ITEM_GROUPS[groupFilter]:' / ARQUIVO DE MERCADORIAS');$('#catalogCount').textContent=String(items.length).padStart(2,'0')+' ITENS';const rarity={common:'STOCK / 2000',rare:'RARE FIND',limited:'T.S. EXCLUSIVE'};const bg={consumivel:'#efd8c6',arma:'#d3e1e0',protecao:'#ebd4e3',acessorio:'#ece1b5',especial:'#d6c5dc'};$('#catalogGrid').innerHTML=items.length?items.map((i,n)=>`<article class="product ${i.stock===0?'is-out':''}"><div class="product-top" style="--product-bg:${bg[i.category]}"><span class="product-serial">#${esc(i.id.toUpperCase())}</span><span class="rarity ${i.rarity}">${rarity[i.rarity]}</span>${itemGraphic(i)}${i.id===LUCKY_BAG_ID?'<span class="mystery-sticker">★ 1 ITEM SURPRESA</span>':''}</div><div class="product-body"><div class="product-category">${CATEGORY[i.category][0]} // ${esc(i.subtitle)}</div><h3 class="product-name">${esc(i.name)}</h3><p class="product-desc">${esc(i.description)}</p><div class="effect">${icon('acessorio')}<span>${esc(i.effect||'Efeito a definir.')}</span></div><div class="product-foot"><div class="price"><small title="${i.sourcePR!==null?esc(`Tabela de referência: ${i.sourcePR} PR × ¥1.000`):'Valor da loja'}">PREÇO / CASH ONLY</small>${money(i.price)}</div><button class="buy" data-buy="${esc(i.id)}" ${i.stock===0?'disabled':''}>${icon('plus','sm')} ${i.stock===0?'ESGOTADO':'CESTA'}</button></div><div class="product-stock ${i.stock!==-1&&i.stock<=3?'low':''}">${i.stock===-1?'● ESTOQUE CONTÍNUO':i.stock===0?'× FORA DE ESTOQUE':i.stock<=3?`◈ ÚLTIMAS ${i.stock} UNIDADES`:`● ESTOQUE: ${i.stock.toString().padStart(2,'0')} UNIDADES`}</div></div></article>`).join(''):`<div class="empty">${icon('search')}<b>NADA NO ESTOQUE.</b><p>Tente outra busca ou peça para o Tanaka verificar no depósito.</p></div>`;}
function receiptHTML(){const p=current();const lines=cartLines();const total=cartTotal();return `<div class="receipt-head"><div><b>CAIXA Nº 01 ↘</b><small>SEU PEDIDO / CHECKOUT</small></div>${icon('cart','lg')}</div><div class="receipt-paper"><div class="receipt-brand"><b>TANAKA <span>SR.</span></b><small>UNDERGROUND MARKET · 東京</small><br><small><span data-receipt-preview>${showReceiptDate(receiptDateDraft)}</span> // CASH ONLY</small></div><div class="client-box"><small>COMPRADOR / PLAYER SELECT</small><div class="client-row"><select aria-label="Cliente" data-client>${state.profiles.map(q=>`<option value="${esc(q.id)}" ${q.id===p.id?'selected':''}>${esc(q.name)}</option>`).join('')}</select><button class="tiny" type="button" data-client-edit title="Editar saldo ou personagem">${icon('edit','sm')}</button><button class="tiny" type="button" data-client-add title="Adicionar personagem">${icon('plus','sm')}</button></div></div><label class="receipt-date-box"><span>📅 DATA DA COMPRA / NO RPG</span><input type="date" data-receipt-date value="${esc(receiptDateDraft)}" aria-label="Data da compra na campanha" required><small>Você escolhe a data da notinha. Cada compra fica registrada com seu próprio dia.</small></label><div class="wallet"><span>SALDO DISPONÍVEL</span><b>${money(p.wallet)}</b></div><div class="cart-lines">${lines.length?lines.map(({item:i,qty})=>`<div class="cart-line"><div><b>${esc(i.name)}</b>${i.id===LUCKY_BAG_ID?'<small class="mystery-in-cart">★ ROLETA · 1 PRÊMIO POR MALETA</small>':''}<small>${money(i.price)} / UNID.</small><div class="qty"><button type="button" data-qty="${esc(i.id)}" data-step="-1" aria-label="Remover uma unidade de ${esc(i.name)}">−</button><b>${qty}</b><button type="button" data-qty="${esc(i.id)}" data-step="1" aria-label="Adicionar uma unidade de ${esc(i.name)}" ${i.stock!==-1&&qty>=i.stock?'disabled':''}>+</button></div></div><div class="cart-line-price">${money(i.price*qty)}</div></div>`).join(''):`<div class="cart-empty">NENHUM ITEM SELECIONADO.<br>──── ◈ ────<br>O CHEFE NÃO GOSTA DE CURIOSOS.</div>`}</div><div class="totals"><div class="total-row"><span>${cartCount()} UNIDADE(S)</span><span>${money(total)}</span></div><div class="total-row"><span>ENTREGA</span><span>RETIRAR NO BALCÃO</span></div><div class="total-row grand"><span>TOTAL</span><strong>${money(total)}</strong></div>${total>p.wallet?`<div class="total-row danger"><span>SALDO INSUFICIENTE</span><b>FALTAM ${money(total-p.wallet)}</b></div>`:''}</div><button type="button" class="checkout" data-checkout ${!lines.length||total>p.wallet?'disabled':''}>${icon('bag')} CONFIRMAR COMPRA ↗</button><div class="receipt-hint">A compra desconta ¥ do saldo local, atualiza o estoque central e envia o pedido ao Presidente Tanaka.</div><div class="receipt-actions"><button type="button" data-clear-cart>× LIMPAR CESTA</button><button type="button" data-history>≡ VER COMPRAS</button></div><div class="receipt-no">*** THANK YOU, COME AGAIN ***</div></div>`}
function renderReceipt(){const h=receiptHTML();$('#desktopReceipt').innerHTML=h;const mob=$('#mobileReceipt');if(mob)mob.innerHTML=h}
function render(){renderHeader();renderCategories();renderCatalog();renderReceipt()}
function addCart(id){const i=state.items.find(x=>x.id===id);if(!i||!i.visible||i.stock===0)return toast('Item indisponível no momento.',true);let q=Number(cart()[id]||0);if(i.stock!==-1&&q>=i.stock)return toast('Você já colocou todo o estoque disponível na cesta.',true);cart()[id]=q+1;save();renderHeader();renderReceipt();toast('Adicionado: '+i.name)}
function changeQty(id,step){const i=state.items.find(x=>x.id===id);if(!i)return;const next=(Number(cart()[id])||0)+step;if(next<=0)delete cart()[id];else if(i.stock===-1||next<=i.stock)cart()[id]=next;else return toast('Sem mais unidades em estoque.',true);save();renderHeader();renderReceipt()}
function openModal(inner,wide=false,extra=''){const el=document.createElement('div');el.className='shade open '+extra;el.innerHTML=`<div class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true">${inner}</div>`;el.addEventListener('click',e=>{if(e.target===el||e.target.closest('[data-close]'))el.remove()});$('#modals').append(el);return el}
function closeModal(){const a=$('#modals .shade:last-child');if(a)a.remove()}
function modalFrame(title,sub,body){return `<div class="dialog-head"><div><h2>${title}</h2><small>${sub}</small></div><button type="button" class="x" data-close aria-label="Fechar">×</button></div><div class="dialog-body">${body}</div>`}
function openCart(){if(window.innerWidth>1050){$('#desktopReceipt').scrollIntoView({behavior:'smooth',block:'center'});$('#desktopReceipt').style.outline='3px solid #c3f45a';setTimeout(()=>$('#desktopReceipt').style.outline='',700);return}const m=openModal(`<div class="dialog-head"><div><h2>CESTA DE COMPRAS.</h2><small>CHECKOUT / TANAKA SR.</small></div><button class="x" data-close aria-label="Fechar">×</button></div><div class="dialog-body"><aside class="receipt-panel" id="mobileReceipt"></aside></div>`,false,'cart-shade');renderReceipt();}
function customerEditor(create=false){const p=create?{name:'',wallet:25000}:current();const html=modalFrame(create?'NOVO COMPRADOR.':'EDITAR COMPRADOR.','SALDO MANUAL / INDEPENDENTE DA FICHA',`<form id="customerForm" class="form-grid"><label class="field full"><span>NOME DO PERSONAGEM</span><input required maxlength="80" name="name" value="${esc(p.name)}" placeholder="Nome do personagem"></label><label class="field full"><span>SALDO EM IENES (¥)</span><input required name="wallet" type="number" min="0" step="1" value="${p.wallet}"></label><div class="field full"><div class="subtle">O saldo é registrado apenas neste HTML. Você pode alterá-lo diretamente entre sessões de RPG.</div></div><div class="dialog-actions field full">${!create&&p.id!=='visitor'?'<button type="button" class="action danger" data-remove-client>EXCLUIR</button>':''}<button type="button" class="action light" data-close>CANCELAR</button><button class="action lime" type="submit">SALVAR PERSONAGEM</button></div></form>`);const m=openModal(html);m.querySelector('#customerForm').addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),name=String(fd.get('name')||'').trim(),wallet=Number(fd.get('wallet'));if(!name||!Number.isSafeInteger(wallet)||wallet<0)return toast('Preencha nome e saldo com valores válidos.',true);if(create){const id=uid();state.profiles.push({id,name,wallet});state.currentProfile=id;state.carts[id]={}}else Object.assign(current(),{name,wallet});save();m.remove();render();toast('Comprador atualizado.')});m.querySelector('[data-remove-client]')?.addEventListener('click',()=>{if(!confirm('Excluir este personagem, o saldo e a cesta dele? O histórico de compras permanece.'))return;delete state.carts[p.id];state.profiles=state.profiles.filter(q=>q.id!==p.id);state.currentProfile=state.profiles[0].id;save();m.remove();render();toast('Personagem excluído.')})}
function receiptText(s){const f=n=>money(n);return ['TANAKA SR. // UNDERGROUND','=================================',`RECIBO #${String(s.no).padStart(4,'0')}`,`CAMPANHA: ${s.shopDate}`,`CLIENTE: ${s.buyer}`,`REGISTRADO: ${new Date(s.timestamp).toLocaleString('pt-BR')}`,'---------------------------------',...s.lines.map(l=>`${l.qty}x ${l.name}\n    ${f(l.price)} x ${l.qty} = ${f(l.qty*l.price)}`),'---------------------------------',...(Array.isArray(s.prizes)&&s.prizes.length?['★ BRINDES DA MALETA LACRADA',...s.prizes.map((it,n)=>`  ${n+1}. ${it.name} — GRÁTIS`),'---------------------------------']:[]),`TOTAL: ${f(s.total)}`,`SALDO RESTANTE: ${f(s.balanceAfter)}`,'=================================','SEM DEVOLUÇÕES. — TANAKA SENIOR'].join('\n')}
function showReceipt(s){lastReceipt=s;const m=openModal(modalFrame(`RECIBO Nº ${String(s.no).padStart(4,'0')}.`,'VENDA REGISTRADA // TRANSAÇÃO CONCLUÍDA',`<div class="modal-receipt">${esc(receiptText(s))}</div><div class="dialog-actions"><button class="action light" type="button" data-receipt-print>IMPRIMIR</button><button class="action" type="button" data-receipt-download>↓ BAIXAR .TXT</button><button class="action lime" type="button" data-receipt-copy>COPIAR RECIBO</button></div>`));m.querySelector('[data-receipt-copy]').onclick=()=>copyText(receiptText(s));m.querySelector('[data-receipt-download]').onclick=()=>download(`tanaka_recibo_${String(s.no).padStart(4,'0')}.txt`,receiptText(s),'text/plain;charset=utf-8');m.querySelector('[data-receipt-print]').onclick=()=>{const w=window.open('','_blank','width=440,height=640');if(!w)return toast('Permita pop-ups para imprimir.',true);w.document.write('<!DOCTYPE html><meta charset="utf-8"><title>Recibo Tanaka</title><pre style="font:13px/1.55 Consolas,monospace;padding:15px;white-space:pre-wrap">'+esc(receiptText(s))+'</pre>');w.document.close();w.focus();w.print()}}
function copyText(t){if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(t).then(()=>toast('Recibo copiado.')).catch(()=>fallbackCopy(t));else fallbackCopy(t)}
function fallbackCopy(t){const a=document.createElement('textarea');a.value=t;a.style.position='fixed';a.style.left='-200vw';document.body.append(a);a.select();try{document.execCommand('copy');toast('Recibo copiado.')}catch(e){toast('Não foi possível copiar; baixe o recibo .TXT.',true)}a.remove()}

// TANAKA SR. // MYSTERY DRAW
const LUCKY_BAG_ID='sh-017';
function luckyRandom(max){
 if(!Number.isInteger(max)||max<1)throw new RangeError('Sorteio vazio.');
 if(globalThis.crypto?.getRandomValues){
   const n=new Uint32Array(1),limit=4294967296-(4294967296%max);
   do{crypto.getRandomValues(n)}while(n[0]>=limit);
   return n[0]%max;
 }
 return Math.floor(Math.random()*max);
}
function eligibleLuckyItems(lines=[]){
 const purchased=new Map(lines.filter(l=>l.item.id!==LUCKY_BAG_ID).map(l=>[l.item.id,l.qty]));
 return state.items.filter(it=>it.id!==LUCKY_BAG_ID&&it.visible&&it.stock!==0&&(it.stock===-1||it.stock>(purchased.get(it.id)||0)));
}
function mysteryCapacity(items,lines){
 const bought=new Map(lines.filter(l=>l.item.id!==LUCKY_BAG_ID).map(l=>[l.item.id,l.qty]));
 return items.some(it=>it.stock===-1)?Infinity:items.reduce((n,it)=>n+Math.max(0,it.stock-(bought.get(it.id)||0)),0);
}
function pickMysteryPrizes(count){
 const prizes=[],pool=state.items.filter(it=>it.id!==LUCKY_BAG_ID&&it.visible&&it.stock!==0).map(it=>({id:it.id,name:it.name,icon:it.icon,rarity:it.rarity}));
 for(let k=0;k<count;k++){
   const eligible=state.items.filter(it=>it.id!==LUCKY_BAG_ID&&it.visible&&it.stock!==0);
   if(!eligible.length)throw Error('O depósito está sem brindes.');
   const item=eligible[luckyRandom(eligible.length)];
   prizes.push({id:item.id,name:item.name,rarity:item.rarity});
   if(item.stock!==-1)item.stock--;
 }
 return {prizes,pool};
}
function showMysteryRoulette(s,pool){
  const prizes=Array.isArray(s.prizes)?s.prizes:[];
  if(!prizes.length)return showReceipt(s);
  const artFor=id=>{
    const it=state.items.find(i=>i.id===id);
    return it?.image?`<img src="${esc(it.image)}" alt="" decoding="async" loading="lazy">`:(it?icon(it.icon):icon('especial'));
  };
  const m=openModal(`<div class="dialog-head lucky-heading"><div><h2>TANAKA // MYSTERY DRAW.</h2><small>NO REFUNDS · 1 PRÊMIO POR MALETA · SOMENTE IENES</small></div><span class="lucky-live">● LIVE DRAW</span></div><div class="dialog-body lucky-body"><div class="lucky-count" aria-live="polite"></div><div class="lucky-topline">★ SENHORAS E SENHORES, O PRÊMIO VEM AÍ ★</div><div class="lucky-window"><div class="lucky-track"></div><span class="lucky-pointer lucky-pointer-top">▼</span><span class="lucky-pointer lucky-pointer-bottom">▲</span></div><div class="lucky-result" hidden aria-live="polite"></div><div class="lucky-controls"><span class="lucky-status" aria-live="polite">INICIANDO A ROLETA...</span><button type="button" class="action light" data-lucky-skip>REVELAR AGORA ↗</button><button type="button" class="action lime" data-lucky-next hidden>VER RECIBO →</button></div><div class="lucky-footer">TANAKA ENTERPRISES · SUA SORTE, SEU PROBLEMA · ★★★</div></div>`,true,'lucky-shade');
  m.addEventListener('click',e=>{if(e.target===m)e.stopImmediatePropagation()},true);
  let at=0,finished=false,timer=0,finalX=0;
  const count=m.querySelector('.lucky-count'),track=m.querySelector('.lucky-track'),view=m.querySelector('.lucky-window'),result=m.querySelector('.lucky-result'),status=m.querySelector('.lucky-status'),skip=m.querySelector('[data-lucky-skip]'),next=m.querySelector('[data-lucky-next]');
  // A seleção do item ocorre no pagamento. A faixa contém ESSE MESMO item em
  // uma posição fixa, que é medida na tela antes de iniciar a animação.
  const card=(it,target=false)=>`<div class="lucky-card ${target?'lucky-target-card':''}" data-wheel-id="${esc(it.id)}"><span class="lucky-card-art">${target?artFor(it.id):icon(it.icon||'especial')}</span><b>${esc(it.name||'MERCADORIA')}</b><small>${it.rarity==='limited'?'T.S. EXCLUSIVE':it.rarity==='rare'?'RARE FIND':'STOCK / 2000'}</small></div>`;
  const targetEl=()=>track.querySelector('.lucky-target-card');
  const targetX=()=>{const tile=targetEl();return tile?view.clientWidth/2-(tile.offsetLeft+tile.offsetWidth/2):0};
  const snapToWinner=()=>{
    finalX=targetX();
    track.style.transition='none';track.style.transform=`translate3d(${finalX}px,0,0)`;
  };
  const reveal=()=>{
    if(finished||!m.isConnected)return;
    finished=true;clearTimeout(timer);track.removeEventListener('transitionend',transitionDone);
    snapToWinner(); // inclusive ao clicar REVELAR AGORA ou no modo de movimento reduzido
    const prize=prizes[at];
    // O id mostrado sob as setas, o resultado e o recibo têm a mesma origem.
    const visual=targetEl();
    if(visual&&visual.dataset.wheelId!==prize.id){console.error('Roleta: prêmio visual diferente do recibo');return}
    view.classList.add('is-finished');
    result.hidden=false;
    result.innerHTML=`<div class="lucky-sparks" aria-hidden="true">✦ ✧ ★ ✧ ✦</div><div class="lucky-prize-art">${artFor(prize.id)}</div><div class="lucky-prize-copy"><span>★ O PRESIDENTE APROVOU SEU PRÊMIO ★</span><h3>${esc(prize.name)}</h3><p>1 unidade · GRÁTIS · ITEM ${at+1} DE ${prizes.length}</p></div>`;
    status.textContent='★ PRÊMIO NO CENTRO DA ROLETA · ADICIONADO AO RECIBO!';
    skip.hidden=true;next.hidden=false;next.textContent=at+1<prizes.length?'PRÓXIMA MALETA →':'VER RECIBO →';
  };
  const transitionDone=e=>{if(e.target===track&&e.propertyName==='transform')reveal()};
  function spin(){
    clearTimeout(timer);track.removeEventListener('transitionend',transitionDone);
    finished=false;result.hidden=true;skip.hidden=false;next.hidden=true;view.classList.remove('is-finished');
    count.textContent=`ABERTURA ${at+1} / ${prizes.length} · RODADA ${String(s.no).padStart(4,'0')}`;
    status.textContent='SORTEANDO UMA MERCADORIA DO DEPÓSITO...';
    const winner=prizes[at];
    const fallback=pool?.length?pool:[{id:winner.id,name:winner.name,rarity:winner.rarity,icon:'especial'}];
    const pick=()=>fallback[luckyRandom(fallback.length)];
    const tiles=Array.from({length:42},pick);
    const target=fallback.find(it=>it.id===winner.id)||{...winner,icon:state.items.find(it=>it.id===winner.id)?.icon||'especial'};
    const targetIndex=tiles.length;
    tiles.push(target,pick(),pick());
    track.style.transition='none';track.style.transform='translate3d(0,0,0)';
    track.innerHTML=tiles.map((it,i)=>card(it,i===targetIndex)).join('');
    track.dataset.winnerId=winner.id;
    // offsetLeft mede a posição REAL da carta; a conta não depende do tamanho
    // presumido da carta, do zoom, do espaçamento CSS ou da largura do celular.
    finalX=targetX();
    const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    if(reduced){snapToWinner();timer=setTimeout(reveal,500);return}
    requestAnimationFrame(()=>requestAnimationFrame(()=>{
      if(!m.isConnected||finished)return;
      finalX=targetX();
      track.addEventListener('transitionend',transitionDone);
      track.style.transition='transform 4500ms cubic-bezier(.12,.78,.13,1)';
      track.style.transform=`translate3d(${finalX}px,0,0)`;
    }));
    timer=setTimeout(reveal,5250); // reserva caso o navegador não dispare transitionend
  }
  skip.addEventListener('click',reveal);
  next.addEventListener('click',()=>{if(!finished)return;if(++at<prizes.length){spin()}else{m.remove();showReceipt(s)}});
  spin();
}

function tanakaTxnId(){
 if(globalThis.crypto?.randomUUID)return crypto.randomUUID();
 const b=new Uint8Array(16);crypto.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;
 const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');
 return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;
}
function tanakaCartSignature(profile,date,lines,total){
 return JSON.stringify({buyer:profile.id,buyerName:profile.name,date,total,lines:lines.map(({item:i,qty})=>[i.id,qty]).sort((a,b)=>a[0].localeCompare(b[0]))});
}
function tanakaHasPendingCheckout(signature){
 try{const p=JSON.parse(localStorage.getItem('tanaka_online_pending_checkout_v2')||'null');
   return p?.signature===signature&&/^[0-9a-f-]{36}$/i.test(p.txnId);
 }catch{return false;}
}
function checkout(){
 const p=current(),lines=cartLines(),total=cartTotal();
 const pendingRetry=tanakaHasPendingCheckout(tanakaCartSignature(p,receiptDateDraft,lines,total));
 if(!lines.length)return toast('A cesta está vazia.',true);
 if(!validReceiptDate(receiptDateDraft))return toast('Selecione uma data válida para a notinha.',true);
 if(total>p.wallet)return toast('Saldo insuficiente em ienes.',true);
 if(!pendingRetry&&lines.some(({item:i,qty})=>i.stock!==-1&&i.stock<qty))return toast('O estoque mudou. Reveja a cesta.',true);
 const bagQty=lines.find(l=>l.item.id===LUCKY_BAG_ID)?.qty||0;
 if(!pendingRetry&&bagQty>0&&mysteryCapacity(eligibleLuckyItems(lines),lines)<bagQty)return toast('Não há brindes suficientes no depósito para essas maletas.',true);
 const m=openModal(modalFrame('FECHAR A CONTA?','CONFIRMAÇÃO / CAIXA CENTRAL TANAKA',`<div class="confirmation-box"><h3>${money(total)}</h3><p><b>Comprador:</b> ${esc(p.name)}<br><b>Itens:</b> ${cartCount()} unidade(s)<br><b>Saldo após a compra:</b> ${money(p.wallet-total)}</p><label class="checkout-confirm-date"><span>📅 DATA DA COMPRA / NA CAMPANHA</span><input type="date" id="confirmReceiptDate" value="${esc(receiptDateDraft)}" required aria-label="Data da compra na campanha"><small>Essa é a data que ficará salva neste recibo, independentemente da data real.</small></label><p><b>◈ CAIXA ONLINE:</b> o Presidente Tanaka receberá este pedido e o estoque central será atualizado para todos os jogadores.</p>${bagQty?`<p class="lucky-checkout-notice">★ ${bagQty} MALETA(S): o prêmio será escolhido pelo depósito central e a roleta revelará o resultado após o pagamento.</p>`:''}</div><div class="dialog-actions"><button class="action light" type="button" data-close>VOLTAR</button><button class="action hot" type="button" id="confirmPurchase">CONFIRMAR PAGAMENTO →</button></div>`));
 let purchaseCommitted=false;
 const pendingKey='tanaka_online_pending_checkout_v2';
 const confirmButton=m.querySelector('#confirmPurchase');
 const confirmDate=m.querySelector('#confirmReceiptDate');
 confirmButton.onclick=async()=>{
   if(purchaseCommitted)return;
   const selectedDate=confirmDate.value;
   if(!validReceiptDate(selectedDate)){confirmDate.reportValidity();return toast('Escolha uma data válida para a compra.',true);}
   const signature=tanakaCartSignature(p,selectedDate,lines,total);
   const retry=tanakaHasPendingCheckout(signature);
   if(total>p.wallet||(!retry&&lines.some(({item:i,qty})=>i.stock!==-1&&i.stock<qty)))return toast('Saldo ou estoque alterado. Revise a compra.',true);
   if(!retry&&bagQty>0&&mysteryCapacity(eligibleLuckyItems(lines),lines)<bagQty)return toast('Brindes esgotados. Revise a compra.',true);
   if(!window.TANAKA_ONLINE?.connected?.())return toast('O caixa central está offline. Aguarde a conexão para não perder o pedido.',true);
   let clientTxnId=tanakaTxnId();
   try{
     const pending=JSON.parse(localStorage.getItem(pendingKey)||'null');
     if(pending?.signature===signature&&/^[0-9a-f-]{36}$/i.test(pending.txnId))clientTxnId=pending.txnId;
     localStorage.setItem(pendingKey,JSON.stringify({signature,txnId:clientTxnId,since:new Date().toISOString()}));
   }catch(e){console.warn('[TANAKA] Não foi possível memorizar o pedido pendente:',e)}
   purchaseCommitted=true;confirmButton.disabled=true;confirmButton.textContent='REGISTRANDO NO CAIXA...';
   let remote;
   try{
     remote=await window.TANAKA_ONLINE.purchase({
       txnId:clientTxnId,buyer:p.name,shopDate:selectedDate,
       lines:lines.map(({item:i,qty})=>({id:i.id,qty})),
       expectedTotal:total,balanceAfter:p.wallet-total
     });
   }catch(err){
     purchaseCommitted=false;confirmButton.disabled=false;confirmButton.textContent='CONFIRMAR PAGAMENTO →';
     // Rejeição definitiva: permita criar outra transação. Em queda de rede, preserve o ID para recuperação sem duplicar a compra.
     if(/Estoque insuficiente|O preço foi alterado|Mercadoria indisponível|Item indisponível/i.test(String(err?.message||err))){
       try{localStorage.removeItem(pendingKey)}catch(e){}
     }
     window.TANAKA_ONLINE?.sync?.();
     return toast('CAIXA CENTRAL: '+String(err?.message||err),true);
   }
   // O banco já consumiu o estoque. Se este pedido já existe no save, não debite novamente.
   const recorded=state.sales.find(s=>s.clientTxnId===clientTxnId);
   if(recorded){
     try{localStorage.removeItem(pendingKey)}catch(e){}
     m.remove();window.TANAKA_ONLINE?.sync?.();
     return showReceipt(recorded);
   }
   p.wallet-=Number(remote.total??total);
   if(Array.isArray(remote.items)){
     const ids=new Set();
     state.items=remote.items.map(x=>{const it=cleanItem(x);ids.add(it.id);if(!it.image)it.image=DEFAULT_ITEM_IMAGES[it.id]||EXTRA_ITEM_IMAGES[it.id]||'';return it});
     for(const carts of Object.values(state.carts))for(const id of Object.keys(carts))if(!ids.has(id))delete carts[id];
   }
   const prizes=Array.isArray(remote.prizes)?remote.prizes:[];
   const remoteNo=Number(remote.sale_no)||0;
   // Recebimentos locais antigos podem ter a mesma numeração que o caixa central.
   const saleNo=remoteNo&&!state.sales.some(s=>s.no===remoteNo)?remoteNo:Math.max(0,state.saleNo,...state.sales.map(s=>Number(s.no)||0))+1;
   state.saleNo=Math.max(Number(state.saleNo)||0,saleNo);
   const sale={no:saleNo,remoteNo:remoteNo||null,buyerId:p.id,buyer:p.name,lines:Array.isArray(remote.lines)?remote.lines:lines.map(({item:i,qty})=>({id:i.id,name:i.name,qty,price:i.price})),prizes,total:Number(remote.total??total),balanceAfter:p.wallet,shopDate:selectedDate,timestamp:new Date().toISOString(),serverId:remote.sale_id||'',clientTxnId};
   state.sales.push(sale);state.sales=state.sales.slice(-300);state.carts[p.id]={};
   const localSaved=save();
   if(localSaved)try{localStorage.removeItem(pendingKey)}catch(e){}
   receiptDateDraft=selectedDate;
   m.remove();$('#modals .cart-shade')?.remove();render();
   if(!localSaved)toast('Compra registrada no Tanaka, mas o save local não pôde ser gravado. Exporte um backup.',true);
   if(prizes.length)showMysteryRoulette(sale,remote.prize_pool||state.items.filter(i=>i.id!==LUCKY_BAG_ID));else showReceipt(sale);
 };
}
function showHistory(){const p=current(),sales=state.sales.filter(s=>s.buyerId===p.id).slice().reverse();const body=`<div class="subtle">RECIBOS DE ${esc(p.name.toUpperCase())} · ${sales.length} REGISTROS MANTIDOS NESTE NAVEGADOR</div>${sales.length?sales.map((s,ix)=>`<div class="history-row"><div><b>#${String(s.no).padStart(4,'0')} · ${esc(s.shopDate)}</b><small>${esc(s.lines.map(l=>`${l.qty}× ${l.name}`).join(' / ').slice(0,130))}${s.prizes?.length?`<br><em style="color:#b72a70;font-weight:900">★ BRINDES: ${esc(s.prizes.map(p=>p.name).join(', ').slice(0,130))}</em>`:''}</small></div><div><strong>${money(s.total)}</strong><br><button class="tiny" type="button" data-view-sale="${s.no}">RECIBO ↗</button></div></div>`).join(''):'<div class="empty" style="min-height:150px;color:#171417;background:#fff8e8">AINDA NÃO HÁ COMPRAS.</div>'}<div class="dialog-actions"><button class="action light" data-close>FECHAR</button></div>`;const m=openModal(modalFrame('ARQUIVO DE VENDAS.','RECIBOS / COMPRAS ANTERIORES',body));m.addEventListener('click',e=>{const b=e.target.closest('[data-view-sale]');if(!b)return;const s=state.sales.find(s=>s.no===Number(b.dataset.viewSale));if(s)showReceipt(s)})}
function download(filename,data,mime){const blob=new Blob([data],{type:mime}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.append(a);a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);a.remove()}
function exportSave(){download(`tanaka_shop_save_${state.shopDate}.json`,JSON.stringify(JSON.parse(compactStateForStorage()),null,2),'application/json;charset=utf-8');toast('Save exportado em JSON.')}
function importSave(file){if(!file)return;if(file.size>12*1024*1024)return toast('O save excede 12 MB.',true);const reader=new FileReader();reader.onload=()=>{try{const candidate=cleanState(JSON.parse(reader.result));if(!confirm('Importar este save vai substituir o catálogo, os saldos e as compras atuais. Continuar?'))return;state=candidate;receiptDateDraft=state.shopDate;filter='all';search='';sort='default';groupFilter='all';$('#effectFilter').value='all';$('#search').value='';$('#sort').value='default';save();render();toast('Save importado com sucesso.')}catch(e){toast('Arquivo incompatível: '+e.message,true)}};reader.readAsText(file,'utf-8')}
function resetShop(){if(!confirm('REINICIAR: isto apaga o catálogo editado, os saldos e o histórico local. Exporte um save antes de continuar.'))return;if(!confirm('Última confirmação: restaurar o catálogo de exemplo?'))return;state=makeDefault();receiptDateDraft=state.shopDate;save();filter='all';search='';sort='default';groupFilter='all';$('#effectFilter').value='all';$('#search').value='';$('#sort').value='default';render();toast('Loja restaurada para o catálogo de exemplo.')}
function admin(){return; // Acesso exclusivo da versão GM.
const body=`<div class="dialog-tabs"><button type="button" class="${adminTab==='catalog'?'active':''}" data-admin-tab="catalog">CATÁLOGO</button><button type="button" class="${adminTab==='settings'?'active':''}" data-admin-tab="settings">CONFIGURAÇÕES</button></div><div id="adminContent"></div>`;const m=openModal(`<div class="dialog-head"><div><h2>BASTIDORES / ESTOQUE.</h2><small>PAINEL LOCAL DO NARRADOR · SEM SENHA</small></div><button class="x" data-close aria-label="Fechar">×</button></div>${body}`,true);const view=()=>{m.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('active',b.dataset.adminTab===adminTab));const c=m.querySelector('#adminContent');c.className='dialog-body';if(adminTab==='settings'){c.innerHTML=`<div class="setting-card"><b>PERSONALIZAÇÃO DA LOJA</b><p>Data da campanha usada nos recibos. A data inicial é ilustrativa. Os 59 produtos novos foram adaptados das imagens fornecidas. Câmbio ilustrativo desta loja: 1 PR de referência = ¥1.000. Não é uma taxa canônica de Persona — Phobia; os preços são editáveis.</p><label class="field"><span>DATA DA CAMPANHA</span><input type="date" id="adminDate" value="${esc(state.shopDate)}"></label><button type="button" class="action lime" style="margin-top:8px" id="saveSettings">SALVAR DATA</button></div><div class="setting-card"><b>BACKUP / ARQUIVO</b><p>Salve ou restaure toda a loja — incluindo personagens, ienes, estoque, vendas e fotos cadastradas. A loja não se conecta à ficha.</p><div class="dialog-actions"><button class="action light" id="adminExport">↓ EXPORTAR</button><button class="action" id="adminImport">↑ IMPORTAR</button></div></div>`;c.querySelector('#saveSettings').onclick=()=>{const v=c.querySelector('#adminDate').value;if(!/^\d{4}-\d\d-\d\d$/.test(v))return toast('Selecione uma data válida.',true);state.shopDate=v;receiptDateDraft=v;save();render();toast('Data atualizada.')};c.querySelector('#adminExport').onclick=exportSave;c.querySelector('#adminImport').onclick=()=>$('#importFile').click();}else{c.innerHTML=`<div class="setting-card"><b>CADASTRO DE MERCADORIAS / ${state.items.length} ITENS</b><p>Adicione quantos produtos quiser. O editor altera os preços, as descrições, os efeitos, as imagens e a quantidade disponível.</p><button class="action lime" data-new-item>＋ CADASTRAR MERCADORIA</button></div><label class="field"><span>BUSCAR NO ESTOQUE</span><input id="adminSearch" type="search" placeholder="Nome, categoria…"></label><div class="admin-list" id="adminList"></div>`;const inp=c.querySelector('#adminSearch'),renderList=()=>{const q=inp.value.toLowerCase();c.querySelector('#adminList').innerHTML=state.items.filter(it=>`${it.name} ${CATEGORY[it.category][0]}`.toLowerCase().includes(q)).map(it=>`<div class="admin-line"><div style="display:flex;gap:9px;align-items:center">${icon(it.icon)}<div><b>${it.visible?'':'[OCULTO] '}${esc(it.name)}</b><small>${esc(CATEGORY[it.category][0])} · ESTOQUE ${it.stock===-1?'∞':it.stock}</small></div></div><span>${money(it.price)}</span><button type="button" data-edit-item="${esc(it.id)}">EDITAR</button></div>`).join('')||'<p>Nenhuma mercadoria encontrada.</p>'};inp.oninput=renderList;renderList();c.querySelector('[data-new-item]').onclick=()=>productEditor(null,()=>{view();render()});c.querySelector('#adminList').onclick=e=>{const b=e.target.closest('[data-edit-item]');if(b)productEditor(state.items.find(i=>i.id===b.dataset.editItem),()=>{view();render()})}}};m.querySelectorAll('[data-admin-tab]').forEach(b=>b.addEventListener('click',()=>{adminTab=b.dataset.adminTab;view()}));view()}
function productEditor(item,done){const isNew=!item;const i=item?{...item}:{id:uid(),category:'consumivel',name:'',subtitle:'',description:'',effect:'',price:0,rarity:'common',stock:5,icon:'bottle',image:'',visible:true};editorImage=i.image||'';const f=`<form id="itemForm"><div class="form-grid"><label class="field full"><span>NOME DA MERCADORIA *</span><input name="name" required maxlength="120" value="${esc(i.name)}" placeholder="Ex.: Tônico de emergência"></label><label class="field full"><span>SUBTÍTULO / ETIQUETA</span><input name="subtitle" maxlength="100" value="${esc(i.subtitle)}" placeholder="Ex.: SÉRIE LIMITADA / 2000"></label><label class="field"><span>CATEGORIA</span><select name="category">${Object.entries(CATEGORY).filter(([k])=>k!=='all').map(([k,[v]])=>`<option value="${k}" ${i.category===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>RARIDADE / ETIQUETA</span><select name="rarity"><option value="common" ${i.rarity==='common'?'selected':''}>COMUM</option><option value="rare" ${i.rarity==='rare'?'selected':''}>RARO</option><option value="limited" ${i.rarity==='limited'?'selected':''}>EXCLUSIVO</option></select></label><label class="field"><span>PREÇO (¥)</span><input name="price" type="number" required min="0" step="1" value="${i.price}"></label><label class="field"><span>ESTOQUE (−1 = ILIMITADO)</span><input name="stock" type="number" required min="-1" step="1" value="${i.stock}"></label><label class="field full"><span>TIPO DE EFEITO / FILTRO</span><select name="group">${Object.entries(ITEM_GROUPS).filter(([g])=>g!=='all').map(([g,label])=>`<option value="${g}" ${i.group===g?'selected':''}>${label}</option>`).join('')}</select></label><label class="field full"><span>DESCRIÇÃO DE CATÁLOGO</span><textarea name="description" maxlength="1200">${esc(i.description)}</textarea></label><label class="field full"><span>EFEITO / MECÂNICA</span><textarea name="effect" maxlength="1200">${esc(i.effect)}</textarea></label><section class="icon-picker" aria-label="Ilustração padrão"><div class="icon-picker-title"><b>ILUSTRAÇÃO // MERCADORIA</b><small>${ICON_LIBRARY.length} MODELOS</small></div><div class="icon-preview" aria-live="polite"></div><div class="icon-picker-tools"><label class="field"><span>BUSCAR ÍCONE</span><input type="search" data-icon-search placeholder="Espada, guitarra, remédio…"></label><label class="field"><span>TIPO DE ILUSTRAÇÃO</span><select data-icon-group><option value="">Todos os tipos</option>${[...new Set(ICON_LIBRARY.map(v=>v.group))].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label></div><div class="icon-grid" role="group" aria-label="Escolha uma ilustração"></div><div class="icon-count" aria-live="polite"></div><label class="field" style="margin-top:10px"><span>ÍCONE SELECIONADO</span><select name="icon">${[...new Set(ICON_LIBRARY.map(v=>v.group))].map(g=>`<optgroup label="${esc(g)}">${ICON_LIBRARY.filter(v=>v.group===g).map(v=>`<option value="${v.id}" ${i.icon===v.id?'selected':''}>${esc(v.label)}</option>`).join('')}</optgroup>`).join('')}</select></label></section><label class="field"><span>FOTO LOCAL (COMPACTADA)</span><input type="file" id="itemPhoto" accept="image/png,image/jpeg,image/webp,image/gif"></label><label class="field full"><span>OU LINK DIRETO DE IMAGEM (HTTP / HTTPS)</span><input name="imageUrl" type="text" placeholder="https://... (vazio para usar ilustração)" value="${i.image.startsWith('http')?esc(i.image):''}"></label><div class="field full"><div class="checkline"><input name="removeImage" type="checkbox"> <span>REMOVER FOTO E USAR A ILUSTRAÇÃO PADRÃO</span></div></div><div class="field full"><div class="checkline"><input name="visible" type="checkbox" ${i.visible?'checked':''}> <span>VISÍVEL NO CATÁLOGO</span></div><div class="subtle" style="margin-top:8px">Fotos enviadas do computador ficam incorporadas no save local; prefira arquivos pequenos. Imagens por link exigem internet para aparecer.</div></div></div><div class="dialog-actions">${isNew?'':'<button type="button" class="action danger" id="deleteItem">EXCLUIR</button>'}<button type="button" class="action light" data-close>CANCELAR</button><button type="submit" class="action lime">${isNew?'＋ CRIAR MERCADORIA':'SALVAR ALTERAÇÕES'}</button></div></form>`;const m=openModal(modalFrame(isNew?'CADASTRAR ITEM.':'EDITAR MERCADORIA.','TANAKA / STOCK MANAGEMENT',f),true);mountIconPicker(m,i);m.querySelector('#itemPhoto').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>8*1024*1024)return toast('A foto precisa ter menos de 8 MB.',true);try{editorImage=await compressImage(file);m.querySelector('[name=imageUrl]').value='';m.querySelector('[name=removeImage]').checked=false;m.dispatchEvent(new Event('item-photo-ready'));toast('Foto carregada e compactada. Salve a mercadoria.')}catch(err){toast('Não foi possível ler esta imagem.',true)}};m.querySelector('#itemForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const raw=Object.fromEntries(fd.entries());const name=String(raw.name||'').trim(),price=Number(raw.price),stock=Number(raw.stock);if(!name||!Number.isSafeInteger(price)||price<0||!Number.isSafeInteger(stock)||stock< -1)return toast('Informe nome, preço e estoque válidos.',true);const imageUrl=String(raw.imageUrl||'').trim();if(imageUrl&&!/^https?:\/\//i.test(imageUrl))return toast('O link da foto precisa começar com http:// ou https://.',true);const next=cleanItem({...i,...raw,name,price,stock,visible:fd.has('visible'),image:fd.has('removeImage')?'':(imageUrl||editorImage)});if(isNew)state.items.push(next);else Object.assign(item,next);if(!save())return;m.remove();done();toast('Mercadoria salva.')};m.querySelector('#deleteItem')?.addEventListener('click',()=>{if(!confirm(`Excluir "${i.name}" do catálogo?`))return;state.items=state.items.filter(x=>x.id!==i.id);Object.values(state.carts).forEach(c=>delete c[i.id]);save();m.remove();done();toast('Mercadoria removida.')})}
function compressImage(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const c=document.createElement('canvas'),max=420,k=Math.min(1,max/Math.max(im.width,im.height));c.width=Math.max(1,Math.round(im.width*k));c.height=Math.max(1,Math.round(im.height*k));c.getContext('2d',{alpha:false}).drawImage(im,0,0,c.width,c.height);const webp=c.toDataURL('image/webp',.74);resolve(webp.startsWith('data:image/webp')?webp:c.toDataURL('image/jpeg',.76))};im.src=r.result};r.readAsDataURL(file)})}

