const TERMINAL_ORDERS={'night-cache':{name:'PEDIDO ESPECIAL // NIGHT CACHE',desc:'Canal de encomendas noturnas do Tanaka.'},'bside-armory':{name:'PEDIDO ESPECIAL // B-SIDE ARMORY',desc:'Lista paralela de armas e equipamentos fora da vitrine.'},'black-file':{name:'PEDIDO ESPECIAL // PRESIDENT BLACK FILE',desc:'Arquivo reservado do Presidente Tanaka Senior.'}};
function terminalProfile(){if(!state.terminal||typeof state.terminal!=='object')state.terminal={};return state.terminal[state.currentProfile]||(state.terminal[state.currentProfile]={solved:[],unlocks:[]})}
function terminalSolved(key){return terminalProfile().solved.includes(key)}
function terminalEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function runTerminalTests(code,challenge){return new Promise(resolve=>{const workerCode=`self.onmessage=e=>{const {code,tests}=e.data;try{const fn=new Function('input','"use strict";\\n'+code);const results=tests.map((t,index)=>{const got=fn(structuredClone(t.input));return {index,got,expected:t.out,pass:JSON.stringify(got)===JSON.stringify(t.out)}});self.postMessage({ok:true,results})}catch(err){self.postMessage({ok:false,error:String(err&&err.message||err)})}}`;const url=URL.createObjectURL(new Blob([workerCode],{type:'text/javascript'})),w=new Worker(url);let done=false;const finish=v=>{if(done)return;done=true;clearTimeout(timer);w.terminate();URL.revokeObjectURL(url);resolve(v)};const timer=setTimeout(()=>finish({ok:false,error:'Tempo limite excedido. Possível loop infinito.'}),1400);w.onmessage=e=>finish(e.data);w.onerror=e=>finish({ok:false,error:e.message||'Erro no worker.'});w.postMessage({code,tests:challenge.tests})})}
function makeTerminalRewardSale(challenge,key){const p=current(),bagCount=challenge.bags;if(mysteryCapacity(eligibleLuckyItems([]),[])<bagCount)throw Error('O depósito não possui itens suficientes para as maletas desta recompensa.');const oldWallet=p.wallet,oldStock=state.items.map(i=>i.stock),oldNo=state.saleNo,oldSales=state.sales.slice();p.wallet+=challenge.yen;const {prizes,pool}=pickMysteryPrizes(bagCount);const tp=terminalProfile();tp.solved.push(key);if(challenge.unlock&&!tp.unlocks.includes(challenge.unlock))tp.unlocks.push(challenge.unlock);const sale={no:++state.saleNo,buyerId:p.id,buyer:p.name,lines:[{id:`terminal-${key}`,name:`NETTRACE ${challenge.label} // RECOMPENSA`,qty:1,price:0}],prizes,total:0,balanceAfter:p.wallet,shopDate:validReceiptDate(receiptDateDraft)?receiptDateDraft:state.shopDate,timestamp:new Date().toISOString(),terminalReward:{key,yen:challenge.yen,bags:bagCount,unlock:challenge.unlock||null}};state.sales.push(sale);state.sales=state.sales.slice(-300);if(!save()){p.wallet=oldWallet;state.items.forEach((i,j)=>i.stock=oldStock[j]);state.saleNo=oldNo;state.sales=oldSales;tp.solved=tp.solved.filter(x=>x!==key);if(challenge.unlock)tp.unlocks=tp.unlocks.filter(x=>x!==challenge.unlock);throw Error('Não foi possível salvar a recompensa.')}render();return {sale,pool}}
// NETTRACE // autorização de acesso (desafio separado dos prêmios)
const NETTRACE_ACCESS_CHALLENGE={
  intercepted:[71,104,121,108,111],
  starter:`// Os caracteres ASCII foram deslocados +3 pelo Presidente.\n// Inverta esse deslocamento em TODOS os números de input.\n// Monte uma string usando String.fromCharCode() e retorne-a.\nreturn "";`,
  tests:[
    {input:[71,104,121,108,111],out:'Devil'},
    {input:[70,68,87],out:'CAT'},
    {input:[87,68,81,68,78,68],out:'TANAKA'},
    {input:[],out:''}
  ]
};
function openTerminalGate(){
  // Cada comprador resolve o enigma apenas na primeira conexão.
  if(terminalProfile().access)return openTerminal();
  const pid=state.currentProfile,challenge=NETTRACE_ACCESS_CHALLENGE;
  const html=`<div class="terminal-head"><div><h2>&gt;_ NETTRACE // LOCKED</h2><small>FIREWALL: TANAKA SENIOR · SOLICITAÇÃO DE ACESSO</small></div><span class="terminal-live">● PASSWORD REQUIRED</span></div>
  <div class="terminal-body"><div class="netgate-mark">🔒 TERMINAL BLOQUEADO · QUEBRE A CIFRA PARA RECUPERAR A SENHA DO PRESIDENTE.</div>
  <div class="netgate-grid"><section class="terminal-pane"><h3>01 // INTERCEPTAR A SENHA</h3>
  <div class="netgate-command">Os arquivos do Presidente usam códigos ASCII. Cada caractere da senha foi deslocado <em>+3</em> posições.\n\nInverta o deslocamento para recuperar os caracteres e junte-os numa única palavra.\n\n<em>Exemplo:</em> input = [70, 68, 87] → "CAT"\n\nEscreva apenas o CORPO de resolver(input). Não declare a função inteira. Seu código precisa funcionar com outras mensagens, não apenas com a senha interceptada.</div>
  <div class="netgate-ascii" aria-label="Códigos interceptados">${challenge.intercepted.map(v=>`<span>${v}</span>`).join('')}</div>
  <textarea class="terminal-editor" data-gate-code spellcheck="false" aria-label="Código para decifrar a senha">${terminalEscape(challenge.starter)}</textarea>
  <div class="terminal-actions"><button type="button" class="terminal-action" data-gate-starter>RESTAURAR MODELO</button><button type="button" class="terminal-action primary" data-gate-test>▶ DECIFRAR / EXECUTAR TESTES</button></div>
  </section><section class="terminal-pane"><h3>02 // CONSOLE DE AUTENTICAÇÃO</h3>
  <div class="terminal-output" data-gate-output aria-live="polite">&gt; FIREWALL ATIVO...\n&gt; 4 testes aguardando decodificação.\n&gt; A senha não aparece até o programa passar.</div>
  <div class="netgate-password"><label for="nettracePresidentPassword">SENHA DO PRESIDENTE TANAKA SR.</label>
  <input id="nettracePresidentPassword" data-gate-password type="text" maxlength="20" disabled placeholder="ACESSO BLOQUEADO" autocomplete="off" autocapitalize="off" spellcheck="false">
  <div class="netgate-recovered" data-gate-recovered>🔐 Execute o programa para descobrir a senha.</div>
  <button type="button" class="terminal-action primary" data-gate-enter disabled>DESBLOQUEAR NETTRACE →</button></div>
  </section></div><div class="dialog-actions" style="margin-top:12px"><button type="button" class="action light" data-close>SAIR DO SISTEMA</button></div></div>`;
  const m=openModal(html,true,'terminal-shade terminal-gate-shade');
  const code=m.querySelector('[data-gate-code]'),run=m.querySelector('[data-gate-test]'),out=m.querySelector('[data-gate-output]');
  const pass=m.querySelector('[data-gate-password]'),enter=m.querySelector('[data-gate-enter]'),recovered=m.querySelector('[data-gate-recovered]');
  let discovered='';
  m.querySelector('[data-gate-starter]').onclick=()=>{code.value=challenge.starter;code.focus()};
  code.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const a=code.selectionStart,b=code.selectionEnd;code.value=code.value.slice(0,a)+'  '+code.value.slice(b);code.selectionStart=code.selectionEnd=a+2}});
  const resetAttempt=()=>{if(discovered){discovered='';pass.disabled=true;pass.value='';pass.placeholder='ACESSO BLOQUEADO';enter.disabled=true;recovered.textContent='🔐 Código modificado. Execute novamente para validar.'}};
  code.addEventListener('input',resetAttempt);
  run.onclick=async()=>{
    const src=code.value.trim();if(!src)return toast('Escreva um programa para decifrar a senha.',true);
    resetAttempt();run.disabled=true;out.textContent='> Descompilando transmissão interceptada...\n> Executando testes no processo isolado...';
    const response=await runTerminalTests(src,challenge);
    if(!m.isConnected||state.currentProfile!==pid)return;
    if(!response.ok){out.innerHTML=`<span class="err">ERRO // ${terminalEscape(response.error)}</span>`;run.disabled=false;return}
    const passes=response.results.filter(t=>t.pass).length;
    out.innerHTML=response.results.map(r=>`VERIFICAÇÃO ${r.index+1} / ${challenge.tests.length}: ${r.pass?'<span class="ok">PASS</span>':'<span class="err">FAIL</span>'}`).join('\n');
    if(passes!==challenge.tests.length){out.innerHTML+=`\n\n<span class="err">${challenge.tests.length-passes} verificação(ões) falharam. Ajuste sua solução. A senha permanece oculta.</span>`;run.disabled=false;return}
    discovered=response.results[0].got;
    out.innerHTML+=`\n\n<span class="ok">CIFRA QUEBRADA. SENHA RECONSTRUÍDA: ${terminalEscape(discovered)}\n&gt; Insira a senha no campo para autenticar.</span>`;
    recovered.textContent='✓ SENHA DESCOBERTA: '+discovered+' · Digite-a exatamente como apareceu.';
    pass.disabled=false;pass.placeholder='DIGITE A SENHA';enter.disabled=false;run.disabled=false;pass.focus();
  };
  const authenticate=()=>{
    if(!discovered)return;
    if(pass.value!==discovered||pass.value!=='Devil'){
      out.innerHTML+='\n<span class="err">ACCESS DENIED // Senha incorreta. Verifique letras maiúsculas e minúsculas.</span>';
      pass.focus();pass.select();return;
    }
    const tp=terminalProfile();tp.access=true;
    if(!save()){tp.access=false;out.innerHTML+='\n<span class="err">Não foi possível salvar o acesso. Verifique seu armazenamento.</span>';return}
    m.remove();openTerminal();
  };
  enter.onclick=authenticate;
  pass.addEventListener('keydown',e=>{if(e.key==='Enter')authenticate()});
}

function openTerminal(){if(!terminalProfile().access)return openTerminalGate();const profile=current(),progress=terminalProfile();let selected=Object.keys(TERMINAL_CHALLENGES).find(k=>!progress.solved.includes(k))||'easy';const html=`<div class="terminal-head"><div><h2>&gt;_ TANAKA // NETTRACE</h2><small>LOCALHOST:2000 · CLIENTE ${terminalEscape(profile.name.toUpperCase())} · ACESSO NÃO AUTORIZADO</small></div><span class="terminal-live">● CONNECTION LIVE</span></div><div class="terminal-body"><div class="terminal-banner">Resolva desafios em JavaScript para receber <b>¥, aberturas de Maleta Lacrada e pedidos especiais</b>. Cada desafio paga uma única vez por personagem.</div><div class="terminal-diff-grid" data-terminal-diffs></div><div class="terminal-workspace"><section class="terminal-pane"><h3 data-terminal-title></h3><div class="terminal-problem" data-terminal-problem></div><div class="terminal-example" data-terminal-example></div><textarea class="terminal-editor" spellcheck="false" data-terminal-code></textarea><div class="terminal-actions"><button class="terminal-action" data-terminal-starter>RESTAURAR MODELO</button><button class="terminal-action primary" data-terminal-run>▶ EXECUTAR TESTES</button></div></section><section class="terminal-pane"><h3>CONSOLE // TEST RUNNER</h3><div class="terminal-output" data-terminal-output>&gt; aguardando comando...\n&gt; worker isolado pronto.</div><div class="terminal-orders"><h3>PEDIDOS ESPECIAIS // ACCESS FLAGS</h3><div data-terminal-orders></div></div><div class="terminal-progress" data-terminal-progress></div></section></div><div class="dialog-actions" style="margin-top:12px"><button class="action light" data-close>DESCONECTAR</button></div></div>`;const m=openModal(html,true,'terminal-shade'),diffs=m.querySelector('[data-terminal-diffs]'),title=m.querySelector('[data-terminal-title]'),problem=m.querySelector('[data-terminal-problem]'),example=m.querySelector('[data-terminal-example]'),editor=m.querySelector('[data-terminal-code]'),out=m.querySelector('[data-terminal-output]'),orders=m.querySelector('[data-terminal-orders]'),prog=m.querySelector('[data-terminal-progress]'),run=m.querySelector('[data-terminal-run]'),starter=m.querySelector('[data-terminal-starter]');const renderOrders=()=>{const tp=terminalProfile();orders.innerHTML=Object.entries(TERMINAL_ORDERS).map(([id,o])=>`<div class="terminal-order ${tp.unlocks.includes(id)?'':'locked'}"><div><b>${terminalEscape(o.name)}</b><br>${terminalEscape(tp.unlocks.includes(id)?o.desc:'ACESSO NEGADO // conclua o desafio correspondente.')}</div><span>${tp.unlocks.includes(id)?'UNLOCKED':'LOCKED'}</span></div>`).join('')};const renderDiffs=()=>{const tp=terminalProfile();diffs.innerHTML=Object.entries(TERMINAL_CHALLENGES).map(([k,c])=>`<button type="button" class="terminal-diff ${selected===k?'active':''} ${tp.solved.includes(k)?'done':''}" data-terminal-diff="${k}"><b>${c.label}</b><small>${terminalEscape(c.title)}</small><span class="reward">+${money(c.yen)} · ${c.bags} MALETA${c.bags>1?'S':''}${c.unlock?' · PEDIDO':''}</span></button>`).join('');prog.textContent=`PROGRESSO: ${tp.solved.length}/4 DESAFIOS · ${tp.unlocks.length}/3 PEDIDOS LIBERADOS`;renderOrders()};const selectChallenge=k=>{selected=k;const c=TERMINAL_CHALLENGES[k];title.textContent=`${c.label} // ${c.title}`;problem.textContent=c.problem;example.textContent=c.example;editor.value=c.starter;out.innerHTML=terminalSolved(k)?'<span class="ok">&gt; DESAFIO JÁ CONCLUÍDO. Recompensa registrada.</span>':'&gt; aguardando código...';run.disabled=terminalSolved(k);run.textContent=terminalSolved(k)?'✓ CONCLUÍDO':'▶ EXECUTAR TESTES';renderDiffs()};diffs.addEventListener('click',e=>{const b=e.target.closest('[data-terminal-diff]');if(b)selectChallenge(b.dataset.terminalDiff)});starter.onclick=()=>{editor.value=TERMINAL_CHALLENGES[selected].starter;editor.focus()};editor.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const s=editor.selectionStart,end=editor.selectionEnd;editor.value=editor.value.slice(0,s)+'  '+editor.value.slice(end);editor.selectionStart=editor.selectionEnd=s+2}});run.onclick=async()=>{const c=TERMINAL_CHALLENGES[selected];if(terminalSolved(selected))return;const code=editor.value.trim();if(!code)return toast('Digite uma solução no terminal.',true);run.disabled=true;out.textContent='> compilando solução...\n> executando testes isolados...';const result=await runTerminalTests(code,c);if(!m.isConnected)return;if(!result.ok){out.innerHTML=`<span class="err">ERRO // ${terminalEscape(result.error)}</span>`;run.disabled=false;return}const failed=result.results.filter(r=>!r.pass);out.innerHTML=result.results.map(r=>`TESTE ${r.index+1}: ${r.pass?'<span class="ok">PASS</span>':'<span class="err">FAIL</span>'}\n  esperado: ${terminalEscape(JSON.stringify(r.expected))}\n  recebido: ${terminalEscape(JSON.stringify(r.got))}`).join('\n\n');if(failed.length){out.innerHTML+=`\n\n<span class="err">${failed.length} teste(s) falharam. Corrija e tente de novo.</span>`;run.disabled=false;return}out.innerHTML+=`\n\n<span class="ok">ACCESS GRANTED // RECOMPENSA LIBERADA</span>\n+ ${money(c.yen)}\n+ ${c.bags} abertura(s) de Maleta${c.unlock?'\n+ Pedido especial desbloqueado':''}`;try{const reward=makeTerminalRewardSale(c,selected);renderDiffs();run.textContent='✓ CONCLUÍDO';setTimeout(()=>{if(m.isConnected)m.remove();if(reward.sale.prizes.length)showMysteryRoulette(reward.sale,reward.pool);else showReceipt(reward.sale)},700)}catch(err){out.innerHTML+=`\n<span class="err">RECOMPENSA FALHOU // ${terminalEscape(err.message)}</span>`;run.disabled=false}};selectChallenge(selected)}

